    SNode* m_node;
    CReactionMatchList() { SNode* head = (SNode*)std::malloc(sizeof(SNode)); head->m_next = head; head->m_prev = head; m_node = head; ++g_heads; }
    ~CReactionMatchList() { std::free(m_node); --g_heads; }
