};

void CPackedUIntArray::Initialise(const void* data, unsigned long bits, long stride, unsigned long count)
{
    if (bits > 32)
        bits = 32;
    delete[] PackedInts;
    PackedInts = 0;
    Bits = 0;
    Bias = 0;
    Size = count;
    Bias = CalculateBias(data, bits, stride, count);
    Bits = CountBits(data, bits, stride, count);
    if (Bits > 0)
